// Prints supabase/seed.sql from the branch's SAMPLE catalog: npm run seed:sql
import { sampleCatalog as cigars } from '../src/branches/cigar'
import { sampleCatalog as pipeTobaccos } from '../src/branches/pipe'

const sampleCatalog = [...cigars, ...pipeTobaccos]

const q = (s: string) => `'${s.replace(/'/g, "''")}'`
const lines = [
  '-- GENERATED by scripts/generate-seed.ts. Do not edit by hand.',
  '-- SAMPLE DATA ONLY: placeholder items so the UI works. Not real products.',
  '-- Needs both migrations (init, then makers).',
  'begin;',
]
const key = (name: string) => `lower(regexp_replace(btrim(${q(name)}), '\\s+', ' ', 'g'))`
for (const brand of [...new Set(sampleCatalog.map((i) => i.brand))]) {
  lines.push(`insert into public.makers (name, status) values (${q(brand)}, 'curated') on conflict (name_key) do nothing;`)
}
for (const item of sampleCatalog) {
  lines.push(
    `insert into public.items (id, category, brand, name, attributes, strength, status, maker_id) values (${q(item.id)}, ${q(item.category)}, ${q(item.brand)}, ${q(item.name)}, ${q(JSON.stringify(item.attributes))}::jsonb, ${item.strength ?? 'null'}, ${q(item.status)}, (select id from public.makers where name_key = ${key(item.brand)})) on conflict (id) do update set maker_id = excluded.maker_id;`,
  )
  for (const tag of item.tags ?? []) {
    lines.push(`insert into public.item_tags (item_id, family, descriptor, weight) values (${q(item.id)}, ${q(tag.family)}, ${tag.descriptor ? q(tag.descriptor) : 'null'}, ${tag.weight}) on conflict do nothing;`)
  }
}
lines.push('commit;')
console.log(lines.join('\n'))
